static constexpr const uint8_t* FACE_LUMI_FRAMES[12] = {
    FACE_LUMI_NEUTRAL_F0, FACE_LUMI_NEUTRAL_F1, FACE_LUMI_HAPPY_F0, FACE_LUMI_HAPPY_F1, FACE_LUMI_SAD_F0, FACE_LUMI_SAD_F1, FACE_LUMI_SLEEPING_F0, FACE_LUMI_SLEEPING_F1, FACE_LUMI_EXCITED_F0, FACE_LUMI_EXCITED_F1, FACE_LUMI_STARTLED_F0, FACE_LUMI_STARTLED_F1
};

inline const uint8_t* getFaceFrameData(uint8_t ci, uint8_t faceMood, uint8_t animFrame) {
    static constexpr const uint8_t* const* T[4] = {
        FACE_BYTEE_FRAMES,
        FACE_CTHULHU_FRAMES,
        FACE_JACK_FRAMES,
        FACE_LUMI_FRAMES,
    };
    return T[ci][(faceMood % 6) * 2 + (animFrame & 1)];
}

inline const uint16_t* getFacePalette(uint8_t ci) {
    static constexpr const uint16_t* P[4] = {
        FACE_BYTEE_PAL,
        FACE_CTHULHU_PAL,
        FACE_JACK_PAL,
        FACE_LUMI_PAL,
    };
    return P[ci];
}
